`timescale 1ns/1ps
// D-SYN-1 equivalence: rtl/dual_lane/SHA3_PAD.sv (sha3_pad, constant-bound loop) vs the protected original
// (TB-only renamed copy sha3_pad_orig_dsyn1, generated by scripts/prepare_dsyn1_variants.py).
// Exhaustive over the port: valid_bytes 0..255 x is_final {0,1} x 66 blocks (64 random, all-zero, all-0xFF).
// CHECKS = 256 * 2 * 66 = 33792 (frozen before the first run; docs/decisions/D-SYN-1-crypto-synth-fixes.md).
module tb_dsyn1_sha3_pad_equiv;
  import sha3_pkg::*;
  localparam int NBLK = 66;
  logic [RATE_BYTES*8-1:0] blk, out_var, out_orig;
  logic [$clog2(RATE_BYTES+1)-1:0] vb;
  logic fin;
  int checks = 0, errors = 0, shown = 0;
  // Deterministic 32-bit LCG (portable; XSim rejects seeding the built-in generator this way).
  logic [31:0] lcg_state = 32'h5A3D_0001;
  function automatic logic [31:0] rnd32();
    lcg_state = lcg_state * 32'd1664525 + 32'd1013904223;
    return lcg_state;
  endfunction
  sha3_pad            u_var (.msg_block_in(blk), .valid_bytes(vb), .is_final(fin), .padded_block(out_var));
  sha3_pad_orig_dsyn1 u_ref (.msg_block_in(blk), .valid_bytes(vb), .is_final(fin), .padded_block(out_orig));
  function automatic logic [RATE_BYTES*8-1:0] block_of(input int k);
    logic [RATE_BYTES*8-1:0] b;
    if (k == 0) return '0;
    if (k == 1) return '1;
    for (int w = 0; w < RATE_BYTES*8/32; w++) b[w*32 +: 32] = rnd32();
    return b;
  endfunction
  initial begin
    $display("CONFIG: TOP=tb_dsyn1_sha3_pad_equiv RATE_BYTES=%0d VB_VALUES=%0d BLOCKS=%0d", RATE_BYTES, 1 << $bits(vb), NBLK);
    for (int k = 0; k < NBLK; k++) begin
      blk = block_of(k);
      for (int v = 0; v < (1 << $bits(vb)); v++) begin
        for (int f = 0; f < 2; f++) begin
          vb = v[$bits(vb)-1:0]; fin = f[0]; #1;
          checks++;
          if (out_var !== out_orig) begin
            errors++;
            if (shown < 10) begin shown++; $display("[FAIL] SHA3_PAD_EQUIV block=%0d valid_bytes=%0d is_final=%0d", k, v, f); end
          end
        end
      end
    end
    $display("CHECKS : %0d", checks);
    $display("ERRORS : %0d", errors);
    $display("RESULT : %s", errors == 0 ? "PASS" : "FAIL");
    $finish;
  end
endmodule
